using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEditor;using UnityEngine;using UnityEngine.Rendering;using ParkingLotEnvironment.Training;
namespace ParkingLotEnvironment.CloudPilot {
public static class CargoRepair {
 public static void Apply(GameObject root,string output){var layout=root.GetComponentInChildren<ParkingTrainingLayout>();var cargo=layout.transform.Find("Parked_T_4").gameObject;var blue=new Material(Shader.Find("Standard")){name="BlueGenericCab",color=new Color(.018f,.13f,.39f)};blue.SetFloat("_Metallic",.22f);blue.SetFloat("_Glossiness",.68f);AssetDatabase.CreateAsset(blue,RefinementBuilder.W+"/BlueGenericCab.mat");int changed=0;
  foreach(var r in cargo.GetComponentsInChildren<Renderer>()){var mats=r.sharedMaterials;for(int i=0;i<mats.Length;i++)if(mats[i]&&mats[i].name.ToLowerInvariant().Contains("bodymat"))mats[i]=blue;r.sharedMaterials=mats;}
  foreach(var f in cargo.GetComponentsInChildren<MeshFilter>()){if(f.name.StartsWith("Cargo"))continue;var src=f.sharedMesh;if(!src||!src.isReadable)continue;var vertices=src.vertices;var tris=src.triangles;var used=tris.Distinct().ToArray();var map=used.Select((v,i)=>new{v,i}).ToDictionary(x=>x.v,x=>x.i);var mesh=UnityEngine.Object.Instantiate(src);var nn=src.normals;var uv=src.uv;var uv2=src.uv2;var pos=used.Select(v=>vertices[v]).ToArray();for(int i=0;i<pos.Length;i++){var world=f.transform.TransformPoint(pos[i]);if(world.y>1.85f){world.y=1.85f;pos[i]=f.transform.InverseTransformPoint(world);changed++;}}mesh.Clear();mesh.vertices=pos;if(nn.Length==vertices.Length)mesh.normals=used.Select(v=>nn[v]).ToArray();if(uv.Length==vertices.Length)mesh.uv=used.Select(v=>uv[v]).ToArray();if(uv2.Length==vertices.Length)mesh.uv2=used.Select(v=>uv2[v]).ToArray();mesh.triangles=tris.Select(v=>map[v]).ToArray();mesh.RecalculateBounds();mesh.RecalculateTangents();mesh.name="CargoRepair_"+f.name;AssetDatabase.CreateAsset(mesh,AssetDatabase.GenerateUniqueAssetPath(RefinementBuilder.W+"/"+mesh.name+".asset"));f.sharedMesh=mesh;}
  var rr=cargo.GetComponentsInChildren<Renderer>().Where(r=>r.enabled).ToArray();var b=rr[0].bounds;foreach(var r in rr.Skip(1))b.Encapsulate(r.bounds);var box=cargo.GetComponent<BoxCollider>();box.center=cargo.transform.InverseTransformPoint(b.center);box.size=b.size;var o=layout.obstacles.Single(x=>x.id==cargo.name);o.center=b.center;o.size=b.size;EditorUtility.SetDirty(layout);Physics.SyncTransforms();File.WriteAllText(output+"/layout.json",JsonUtility.ToJson(layout,true));File.AppendAllText(output+"/build-notes.txt","Lowered obsolete cargo bulkhead; blue cab paint; compacted used mesh vertices; changed vertices="+changed+". This is still the generic truck, NOT the unavailable Porter/Bongo model.\n");
 }
}}
